defmodule Solution do def is_isomorphic(s, t), do: compare(s, t, %{}, %{}); defp compare(<<>>, <<>>, _, _), do: true; defp compare(<<a, rest_s::binary>>, <<b, rest_t::binary>>, forward, backward) do if Map.get(forward, a, b) == b and Map.get(backward, b, a) == a do compare(rest_s, rest_t, Map.put(forward, a, b), Map.put(backward, b, a)) else false end end; defp compare(_, _, _, _), do: false end
